<?php declare(strict_types=1);namespace StudPulse\Domain;use StudPulse\Database\DB;use StudPulse\Http\ApiError;use StudPulse\Integrations\{MpeiSchedule,ScheduleSubgroups};final class LibraryTracks{public static function selection(string$user,string$code):array{$row=DB::one('SELECT preferences FROM user_preferences WHERE user_id=?',[$user]);$selected=json_decode($row['preferences']??'{}',true)['subgroups']??[];return($selected['group']??'')===ScheduleSubgroups::groupKey($code)?$selected:[];}public static function catalog(string$code,?array$term=null):array{$monday=new \DateTimeImmutable('monday this week',new \DateTimeZone('Europe/Moscow'));$utc=new \DateTimeZone('UTC');$from=$term?new \DateTimeImmutable($term['begins_at'],$monday->getTimezone()):$monday->modify('-14 days');$to=$term?(new \DateTimeImmutable($term['ends_at'],$monday->getTimezone()))->modify('+1 day'):$monday->modify('+28 days');$schedule=MpeiSchedule::forGroup($code,$from->setTimezone($utc)->format('Y-m-d H:i:s'),$to->setTimezone($utc)->format('Y-m-d H:i:s'));$options=ScheduleSubgroups::options($schedule);$options['subjects']=array_values(array_unique(array_column($schedule->items,'subject_title')));return$options;}public static function forSubject(string$user,string$code,string$title,string$requested=''):?array{$key=ScheduleSubgroups::subject(mb_strtolower($title),'лабораторная');$selected=self::selection($user,$code)[$key]??'';if($requested!==''&&($key===null||!preg_match('/^[a-f0-9]{64}$/D',$requested)||($selected!==''&&$selected!==$requested))){throw new ApiError(422,'LIBRARY_SUBGROUP','Выберите доступную подгруппу предмета');}$variant=$requested!==''?$requested:$selected;if($variant==='')return null;$teacher='';try{foreach(self::catalog($code)['items']as$item){if($item['id']!==$key)continue;foreach($item['choices']as$choice){if($choice['id']===$variant)$teacher=ScheduleSubgroups::folderLabel($choice['label'],$choice['teachers']);}}}catch(ApiError){}if($teacher===''&&$requested!==''&&$requested!==$selected){throw new ApiError(422,'LIBRARY_SUBGROUP','Обновите расписание и выберите подгруппу снова');}return['subject'=>$key,'variant'=>$variant,'teacher'=>$teacher];}public static function canUse(string$user,string$code,array$track):bool{$selected=self::selection($user,$code)[$track['subject']]??'';return$selected===''||$selected===$track['variant'];}}